/// <summary>
/// AVA return Info3 from SalesTable
/// </summary>
/// <returns>Notes</returns>
display Notes avaSalesTableInfo3()
{
    Notes                           ret;
    KCS_SOCSalesTableInfoFields     infoFields;

    if (this.OrderNum)
    {
        switch (this.WorkTransType)
        {
            case WHSWorkTransType::Sales:
                infoFields =  KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, this.OrderNum);
                break;
            case WHSWorkTransType::TransferIssue:
                infoFields =  KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::TransferOrderShip, this.OrderNum);
                break;
        }

        if (infoFields)
        {
            ret = infoFields.InfoField3;
        }            
    }
    return ret;
}

/// <summary>
/// Consolidates <paramref name="_salesLine" /> into the shipment.
/// </summary>
/// <param name = "_salesLine">A sales line.</param>
/// <param name = "_salesTable">A sales order.</param>
public void consolidateSalesLine(SalesLine _salesLine, SalesTable _salesTable)
{
    next consolidateSalesLine(_salesLine, _salesTable);

    this.AVADlvMode = this.AVADlvMode != _salesLine.DlvMode ? '' : _salesLine.DlvMode;
}

/// <summary>
/// Initializes the shipment for a sales order. The shipment Id is not initialized.
/// </summary>
/// <param name = "_salesOrderParameters">Sales order shipment parameters.</param>
public void initShipmentWithoutIdForSalesOrder(WHSWarehouseReleaseSalesOrderParameters _salesOrderParameters)
{
    next initShipmentWithoutIdForSalesOrder(_salesOrderParameters);

    this.AVADlvMode = _salesOrderParameters.SalesLine.DlvMode ? _salesOrderParameters.SalesLine.DlvMode : _salesOrderParameters.SalesOrder.DlvMode;
}
